-- add_normal_investigation_images.sql
-- Run once in the Supabase SQL editor.
--
-- Attaches a real, reusable image to six investigation results that were already authored as
-- normal/unremarkable findings, but had text only (no picture) — same idea as the reusable-image
-- discussion: a normal scan looks the same regardless of the patient's unrelated diagnosis, so one
-- file can back several cases' results. See public/investigation-images/CREDITS.md for source and
-- licence per file (all verified individually — opened and checked, not taken on the filename alone
-- — and licensed for commercial use, since Medikarya is a paid product).
--
-- Each UPDATE replaces the case's whole "tests" array with a version that is IDENTICAL except for one,
-- two or three entries gaining a "result.image" field (jsonb_set can't target inside an array by id,
-- only by index, so the safe way to do this is to replace the whole array with a precomputed,
-- otherwise-unchanged copy rather than guess an index). complete-heart-block-syncope's
-- echocardiography, neonatal-jaundice-breastmilk's Ultrasound Abdomen, and viral-gastroenteritis's
-- Ultrasound Abdomen, X-Ray Abdomen and CT Scan Abdomen keep their existing authored
-- summary/interpretation text untouched, only gaining the image. severe-migraine-with-aura's MRI Brain
-- and CT Brain had NO result
-- at all before this (confirmed: these two tests were completely unauthored) — they get a new, real
-- result now: normal neuroimaging is the standard, expected finding in a migraine workup (imaging is
-- ordered specifically to exclude a secondary cause; a normal result is what supports the diagnosis
-- the case is already built around), so this adds a textbook-standard normal report, not a guess.
--
-- Everything else in every test entry — id, name, category, other tests entirely — is byte-for-byte
-- what was already in the database; only file to check that against is this script's own literals.

update public.cases
set case_json = jsonb_set(case_json::jsonb, '{tests}', '[{"id":"ecg","name":"12-lead ECG","result":{"values":[{"unit":"bpm","value":"82","parameter":"Atrial Rate","referenceRange":"60-100"},{"unit":"bpm","value":"36","parameter":"Ventricular Rate","referenceRange":"60-100"},{"unit":"ms","value":"Variable (dissociated)","parameter":"PR Interval","referenceRange":"120-200"},{"unit":"ms","value":"160","parameter":"QRS Duration","referenceRange":"<120"},{"unit":"","value":"Present","parameter":"AV Dissociation","referenceRange":"Absent"},{"unit":"","value":"Infranodal (LBBB morphology)","parameter":"Ventricular Escape Origin","referenceRange":"N/A"}],"summary":"Complete AV dissociation with a slow regular ventricular escape rhythm at 35-36 bpm.","ecg_parameters":{"axis":"Left axis deviation","pWaves":"Present, regular, occurring independently of QRS complexes","rhythm":"Complete AV block (Third-degree AV block)","finding":"P waves and QRS complexes are completely dissociated. Ventricular escape rhythm is slow at 36 bpm with wide QRS, indicating infranodal (His-Purkinje) origin.","stChanges":"None","atrialRate":82,"prInterval":"Variable — no consistent PR interval (AV dissociation)","qrsDuration":160,"qrsMorphology":"Wide, aberrant — left bundle branch block (LBBB) pattern (infranodal block)","ventricularRate":36},"interpretation":"Complete (third-degree) AV block. Atria and ventricles are beating independently. The slow infranodal escape rhythm at 36 bpm is haemodynamically compromising and directly explains the recurrent Stokes-Adams syncopal attacks.","criticalFindings":true},"category":"Cardiology"},{"id":"continuous-ecg-monitoring","name":"Continuous ECG Monitoring","result":{"values":[{"unit":"hours","value":"6","parameter":"Monitoring Duration","referenceRange":"N/A"},{"unit":"","value":"Absent throughout","parameter":"AV Conduction","referenceRange":"Present"},{"unit":"bpm","value":"34-38","parameter":"Ventricular Escape Rate","referenceRange":"60-100"},{"unit":"","value":"2 episodes noted","parameter":"Pauses >3 sec","referenceRange":"None"}],"summary":"Persistent complete AV block throughout the monitoring period. No return of AV conduction observed.","interpretation":"Persistent complete heart block with no intermittent return of AV conduction. Two significant pauses documented. This confirms a permanent complete heart block requiring pacemaker implantation rather than a transient or reversible block.","criticalFindings":true},"category":"Cardiology"},{"id":"echocardiography","name":"Echocardiography","result":{"values":[{"unit":"%","value":"57","parameter":"LVEF","referenceRange":">55"},{"unit":"","value":"Mild (IVSd 12 mm)","parameter":"LV Hypertrophy","referenceRange":"Absent"},{"unit":"","value":"None significant","parameter":"Valvular Disease","referenceRange":"None"},{"unit":"","value":"Normal throughout","parameter":"Wall Motion","referenceRange":"Normal"},{"unit":"","value":"None","parameter":"Pericardial Effusion","referenceRange":"None"}],"summary":"Preserved systolic function. Mild left ventricular hypertrophy consistent with hypertensive heart disease. No structural cause for conduction block.","interpretation":"Preserved systolic function with mild LVH (hypertensive aetiology). No structural cardiac disease to explain the conduction block. Supports a degenerative fibrosis (Lenègre''s disease) aetiology for the complete heart block.","criticalFindings":false,"image":"/investigation-images/echo-4chamber-normal.jpg"},"category":"Imaging"},{"id":"serum-electrolytes","name":"Serum Electrolytes","result":{"values":[{"unit":"mEq/L","value":"138","parameter":"Sodium","referenceRange":"135-145"},{"unit":"mEq/L","value":"4.1","parameter":"Potassium","referenceRange":"3.5-5.0"},{"unit":"mg/dL","value":"9.2","parameter":"Calcium","referenceRange":"8.5-10.5"},{"unit":"mg/dL","value":"1.9","parameter":"Magnesium","referenceRange":"1.7-2.2"}],"summary":"All electrolytes within normal limits. No electrolyte cause for the conduction disorder.","interpretation":"No electrolyte abnormality. Hyperkalaemia, hypocalcaemia, and hypomagnesaemia — all reversible causes of conduction block — have been excluded.","criticalFindings":false},"category":"Laboratory"},{"id":"blood-glucose","name":"Blood Glucose","result":{"values":[{"unit":"mg/dL","value":"98","parameter":"Fasting Blood Glucose","referenceRange":"70-100"}],"summary":"Fasting blood glucose within normal range.","interpretation":"Normoglycaemia. Hypoglycaemia excluded as a cause of the syncopal episodes.","criticalFindings":false},"category":"Laboratory"}]'::jsonb)
where id = 'complete-heart-block-syncope';

update public.cases
set case_json = jsonb_set(case_json::jsonb, '{tests}', '[{"id":"tsb","name":"Total Serum Bilirubin (TSB)","result":{"values":[],"summary":"Unconjugated hyperbilirubinemia. Values are below exchange transfusion threshold.","interpretation":"Unconjugated hyperbilirubinemia. Values are below exchange transfusion threshold.","criticalFindings":false},"category":"laboratory"},{"id":"dct","name":"Direct Coombs Test (DCT)","result":{"values":[],"summary":"Negative. No evidence of immune hemolysis.","interpretation":"Negative. No evidence of immune hemolysis.","criticalFindings":false},"category":"laboratory"},{"id":"cbc","name":"Complete Blood Count (CBC)","result":{"values":[],"summary":"Normal neonatal indices. No anemia or leukocytosis.","interpretation":"Normal neonatal indices. No anemia or leukocytosis.","criticalFindings":false},"category":"laboratory"},{"id":"blood-group","name":"Blood Group & Rh Typing","result":{"values":[],"summary":"Baby: O Positive. (Mother is also O Positive — no ABO/Rh incompatibility).","interpretation":"Baby: O Positive. (Mother is also O Positive — no ABO/Rh incompatibility).","criticalFindings":false},"category":"laboratory"},{"id":"retic-count","name":"Reticulocyte Count","result":{"values":[],"summary":"Normal.","interpretation":"Normal.","criticalFindings":false},"category":"laboratory"},{"id":"g6pd","name":"G6PD Assay","result":{"values":[],"summary":"Normal enzyme activity.","interpretation":"Normal enzyme activity.","criticalFindings":false},"category":"laboratory"},{"id":"thyroid-profile","name":"Thyroid Profile (T3, T4, TSH)","result":{"values":[],"summary":"Euthyroid.","interpretation":"Euthyroid.","criticalFindings":false},"category":"laboratory"},{"id":"sepsis-screen","name":"Sepsis Screen","result":{"values":[],"summary":"Negative.","interpretation":"Negative.","criticalFindings":false},"category":"laboratory"},{"id":"lft","name":"Liver Function Test (LFT)","result":{"values":[],"summary":"Normal liver enzymes. Only unconjugated bilirubin is elevated.","interpretation":"Normal liver enzymes. Only unconjugated bilirubin is elevated.","criticalFindings":false},"category":"laboratory"},{"id":"usg-abdomen","name":"Ultrasound Abdomen","result":{"values":[],"summary":"Liver is normal in size and echotexture. Gallbladder and biliary tree are normal. No evidence of biliary atresia. Spleen is normal.","interpretation":"Liver is normal in size and echotexture. Gallbladder and biliary tree are normal. No evidence of biliary atresia. Spleen is normal.","criticalFindings":false,"image":"/investigation-images/usg-abdomen-liver-normal.jpg"},"category":"imaging"}]'::jsonb)
where id = 'neonatal-jaundice-breastmilk';

update public.cases
set case_json = jsonb_set(case_json::jsonb, '{tests}', '[{"id":"iem","name":"Immunoelectron Microscopy","result":{"values":[],"summary":"Triple-shelled capsid with wheel-like appearance — consistent with Rotavirus.","interpretation":"Triple-shelled capsid with wheel-like appearance — consistent with Rotavirus.","criticalFindings":false},"category":"imaging"},{"id":"stool-elisa-rotavirus","name":"Stool ELISA for Rotavirus","result":{"values":[],"summary":"Positive for Rotavirus Antigen","interpretation":"Positive for Rotavirus Antigen","criticalFindings":false},"category":"laboratory"},{"id":"cbc","name":"Complete Blood Count (CBC)","result":{"values":[],"summary":"WBC mildly elevated. No eosinophilia. Consistent with viral infection.","interpretation":"WBC mildly elevated. No eosinophilia. Consistent with viral infection.","criticalFindings":false},"category":"laboratory"},{"id":"serum-electrolytes","name":"Serum Electrolytes","result":{"values":[],"summary":"Mild hyponatraemia consistent with diarrhoeal illness.","interpretation":"Mild hyponatraemia consistent with diarrhoeal illness.","criticalFindings":false},"category":"laboratory"},{"id":"rft","name":"Renal Function Test (RFT)","result":{"values":[],"summary":"Mildly elevated urea, consistent with dehydration. No renal failure.","interpretation":"Mildly elevated urea, consistent with dehydration. No renal failure.","criticalFindings":false},"category":"laboratory"},{"id":"stool-routine","name":"Stool Routine & Microscopy","result":{"values":[],"summary":"Watery stool. No RBCs. No WBCs on microscopy. No cysts or ova detected.","interpretation":"Watery stool. No RBCs. No WBCs on microscopy. No cysts or ova detected.","criticalFindings":false},"category":"laboratory"},{"id":"stool-culture","name":"Stool Culture","result":{"values":[],"summary":"No pathogenic bacteria isolated after 48 hours. Viral aetiology confirmed.","interpretation":"No pathogenic bacteria isolated after 48 hours. Viral aetiology confirmed.","criticalFindings":false},"category":"laboratory"},{"id":"usg-abdomen","name":"Ultrasound Abdomen","result":{"values":[],"summary":"No organomegaly. No free fluid. No appendicitis. Normal bowel loops.","interpretation":"No organomegaly. No free fluid. No appendicitis. Normal bowel loops.","criticalFindings":false,"image":"/investigation-images/usg-abdomen-liver-normal.jpg"},"category":"imaging"},{"id":"xray-abdomen","name":"X-Ray Abdomen","result":{"values":[],"summary":"No free air under diaphragm. Normal gas pattern.","interpretation":"No free air under diaphragm. Normal gas pattern.","criticalFindings":false,"image":"/investigation-images/xray-abdomen-normal.jpg"},"category":"imaging"},{"id":"ct-abdomen","name":"CT Scan Abdomen","result":{"values":[],"summary":"No obstruction. No perforation. No acute surgical pathology.","interpretation":"No obstruction. No perforation. No acute surgical pathology.","criticalFindings":false,"image":"/investigation-images/ct-abdomen-pelvis-normal.png"},"category":"imaging"}]'::jsonb)
where id = 'viral-gastroenteritis';

update public.cases
set case_json = jsonb_set(case_json::jsonb, '{tests}', '[{"id":"bp","name":"Blood Pressure Monitoring","category":"vitals"},{"id":"fundoscopy","name":"Fundoscopy","category":"examination"},{"id":"cbc","name":"Complete Blood Count (CBC)","category":"laboratory"},{"id":"mri-brain","name":"MRI Brain","category":"imaging","result":{"summary":"No structural abnormality. No mass, haemorrhage, midline shift or acute infarct.","interpretation":"Normal brain MRI — no secondary structural cause for the headache identified; consistent with a primary headache disorder.","criticalFindings":false,"image":"/investigation-images/mri-brain-normal.jpg"}},{"id":"ct-brain","name":"CT Brain","category":"imaging","result":{"summary":"No acute intracranial haemorrhage, mass effect or midline shift.","interpretation":"Normal CT brain — no evidence of a structural or vascular cause for the headache.","criticalFindings":false,"image":"/investigation-images/ct-brain-normal.png"}}]'::jsonb)
where id = 'severe-migraine-with-aura';

-- Check: should list exactly 7 rows — the 4 case ids above with 1, 1, 3 and 2 imaged tests respectively.
select c.id as case_id, t.value->>'id' as test_id, t.value->'result'->>'image' as image
from public.cases c, jsonb_array_elements(c.case_json->'tests') as t(value)
where c.id in ('complete-heart-block-syncope', 'neonatal-jaundice-breastmilk', 'viral-gastroenteritis', 'severe-migraine-with-aura')
  and t.value->'result'->>'image' is not null;
